Object.assign(rows,workspaceRefinements);
Object.assign(rows,release100Rows);
const playlistPlaceholders={playlistSelection:{selected:{content:'$1'},total:{content:'$2'}},playlistDownload:{count:{content:'$1'}},playlistProgress:{done:{content:'$1'},total:{content:'$2'},failed:{content:'$3'}}};
for (let i=0;i<locales.length;i++) {
  const catalog = Object.fromEntries(Object.entries(rows).map(([key,values]) => {
    if (values.length!==10 || !values[i]) throw new Error(`Missing ${key}/${locales[i]}`);
    return [key,{message:values[i],description:`Alcydeo interface: ${key}`,...(playlistPlaceholders[key]?{placeholders:playlistPlaceholders[key]}:key==='pageStatus'?{placeholders:{current:{content:'$1',example:'1'},total:{content:'$2',example:'6'}}}:key==='managerResults'?{placeholders:{count:{content:'$1',example:'12'}}}:{})}];
  }));
  await mkdir(`apps/extension/public/_locales/${locales[i]}`,{recursive:true});
  await writeFile(`apps/extension/public/_locales/${locales[i]}/messages.json`,JSON.stringify(catalog,null,2)+'\n');
}
await mkdir('packages/i18n',{recursive:true});
await writeFile('packages/i18n/catalogs.json',JSON.stringify(Object.fromEntries(locales.map((l,i)=>[l,Object.fromEntries(Object.entries(rows).map(([k,v])=>[k,v[i]]))])),null,2)+'\n');
console.log(`Generated ${Object.keys(rows).length} native messages × 10 languages`);
